"use client";

import { Switch as SwitchPrimitive } from "@base-ui/react/switch";

import { cn } from "@/lib/utils";
import { controlChecked, focusRing } from "./_shared";

type WithClassName<P> = Omit<P, "className"> & { className?: string };

/**
 * Bold retail Switch: a 2.75rem by 1.5rem grey track with a white knob on the
 * small thumb shadow. On, the track turns the flat black of the primary
 * button and the knob slides to the end.
 */
function Switch({ className, ...props }: WithClassName<SwitchPrimitive.Root.Props>) {
  return (
    <SwitchPrimitive.Root
      data-slot="switch"
      className={cn(
        "peer inline-flex h-6 w-11 shrink-0 cursor-pointer items-center rounded-full border border-transparent bg-(--line-strong) p-0.5",
        "transition-colors duration-fast ease-out",
        "hover:data-[unchecked]:bg-(--control)",
        focusRing,
        "data-[disabled]:cursor-not-allowed data-[disabled]:bg-secondary",
        controlChecked,
        className,
      )}
      {...props}
    >
      <SwitchPrimitive.Thumb
        data-slot="switch-thumb"
        className={cn(
          "pointer-events-none block size-5 rounded-full bg-(--thumb) shadow-(--shadow-thumb)",
          "transition-transform duration-fast ease-out motion-reduce:transition-none",
          "data-[checked]:translate-x-4.5 data-[unchecked]:translate-x-0 rtl:data-[checked]:-translate-x-4.5",
          "data-[disabled]:shadow-none",
        )}
      />
    </SwitchPrimitive.Root>
  );
}
Switch.displayName = "Switch";

export { Switch };
